import data from './commonIssues.json'
import { getWcag } from './wcag'

export type Platform = 'Desktop' | 'iOS' | 'Mobile'
export type Priority = 'Blocker' | 'Critical' | 'Major' | 'Minor'
export type ExampleKind = 'Internal' | 'External' | 'iOS' | 'Android'

export type WorkingExample = {
  kind: ExampleKind
  label: string
  url: string
}

/**
 * One row of the common issues workbook (sheets Desktop, iOS, Mobile).
 * Generated by scripts/convert-common-issues.py; Mobile's "iOS Fixes" and
 * "Android Fixes" columns are merged into `fix` with platform prefixes.
 */
export type CommonIssue = {
  id: string
  platform: Platform
  number: number
  description: string
  expectedBehavior: string
  fix: string
  priority: Priority | ''
  wcag: string[]
  category: string
  comments: string
  examples: WorkingExample[]
}

export const PLATFORMS: Platform[] = ['Desktop', 'iOS', 'Mobile']
export const PRIORITIES: Priority[] = ['Blocker', 'Critical', 'Major', 'Minor']
export const EXAMPLE_KINDS: ExampleKind[] = ['Internal', 'External', 'iOS', 'Android']

export const COMMON_ISSUES = data as CommonIssue[]

export const CATEGORIES: string[] = Array.from(
  new Set(COMMON_ISSUES.map((i) => i.category).filter(Boolean)),
).sort((a, b) => a.localeCompare(b))

function haystack(issue: CommonIssue): string {
  return [
    issue.description,
    issue.expectedBehavior,
    issue.fix,
    issue.category,
    issue.priority,
    issue.platform,
    issue.comments,
    ...issue.wcag,
    ...issue.wcag.map((id) => getWcag(id)?.name ?? ''),
    ...issue.examples.map((e) => e.label),
  ]
    .join(' ')
    .toLowerCase()
}

const INDEX = COMMON_ISSUES.map((issue) => ({
  issue,
  text: haystack(issue),
  desc: issue.description.toLowerCase(),
}))

/** Every whitespace-separated term must match; description and WCAG hits rank higher. */
export function searchCommonIssues(query: string, platform?: Platform | 'All', limit = 30): CommonIssue[] {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean)
  const pool = platform && platform !== 'All' ? INDEX.filter((e) => e.issue.platform === platform) : INDEX
  if (!terms.length) return pool.slice(0, limit).map((e) => e.issue)
  return pool
    .filter((e) => terms.every((t) => e.text.includes(t)))
    .map((e) => {
      let score = 0
      for (const t of terms) {
        if (e.desc.includes(t)) score += 3
        if (e.issue.wcag.some((w) => w.startsWith(t))) score += 3
        if (e.issue.category.toLowerCase().includes(t)) score += 2
      }
      return { issue: e.issue, score }
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((e) => e.issue)
}
